const validation = global.get("smartcareValidation");
if (!validation) { node.error("Validation module unavailable", msg); return null; }
const result = validation.validate(msg.payload, {topic:msg.topic, retained:msg.retain === true});
if (!result.accepted) {
    const match = /^health\/([A-Za-z0-9_-]+)\/vitals$/.exec(msg.topic || "");
    if (!match) { node.error("Invalid source topic", msg); return null; }
    const id = msg.payload && typeof msg.payload.measurement_id === "string" ? msg.payload.measurement_id : null;
    return [null, null, {topic:"health/"+match[1]+"/rejected", payload:JSON.stringify({measurement_id:id,...result})}];
}
const data = msg.payload;
return [
    {payload:"Patient " + data.patient_id + " | " + data.parameter + ": " + data.value + " " + data.unit},
    {topic:"health/"+data.patient_id+"/received", payload:JSON.stringify(data)},
    null
];

const match = /^health\/([A-Za-z0-9_-]+)\/vitals$/.exec(msg.topic || "");
if (!match) return null;
const code = msg.error && msg.error.source && msg.error.source.id === "decode-json" ? "invalid_json" : "validation_unavailable";
return {topic:"health/"+match[1]+"/rejected",payload:JSON.stringify({measurement_id:null,accepted:false,errors:[{code,field:"payload"}]})};
